import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render a plain-text invoice.
 * @param {{ number?: string, customerId: string, customerName: string, issueDate: string, dueDate?: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number, date: string }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // Invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);

  // Customer name
  lines.push(invoice.customerName);

  // Invoice lines with discounts
  for (const line of invoice.lines) {
    const lineAmount = line.qty * line.unitPrice;
    const qtyStr = String(line.qty);
    const priceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(lineAmount);
    lines.push(`${qtyStr}x ${line.name} @ ${priceStr} = ${totalStr}`);

    // Show line discount if present
    if (line.discountPercent && line.discountPercent > 0) {
      const discountAmount = Math.round(lineAmount * line.discountPercent / 100);
      lines.push(`  (discount: -${formatEuros(discountAmount)})`);
    }
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Show VAT line if there's any VAT
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Show voucher if present
  if (invoice.voucher && invoice.voucher.amount > 0) {
    lines.push(`Voucher (${invoice.voucher.code}): -${formatEuros(invoice.voucher.amount)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Show due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Show paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

