    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
    voucher: { code: 'EMPTY', amount: 0 },
  };
  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Voucher'));
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    dueDate: '2026-10-21',
    status: 'issued',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Due: 2026-10-21'));
});

test('renderInvoiceText does not show due date when absent', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Paid: €50.00'));
});

test('renderInvoiceText sums multiple payments', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 20, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
    payments: [
      { amount: 5000, date: '2026-10-15' },
      { amount: 3000, date: '2026-10-20' },
      { amount: 2000, date: '2026-10-25' },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Paid: €100.00'));
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows all features together', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    dueDate: '2026-10-21',
    status: 'partially_paid',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
    voucher: { code: 'SAVE5', amount: 500 },
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Check all elements are present
  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Test Customer'));
  assert.ok(text.includes('Development (hour)'));
  assert.ok(text.includes('(discount: -€10.00)'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Voucher (SAVE5): -€5.00'));
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('Due: 2026-10-21'));
  assert.ok(text.includes('Paid: €50.00'));
});

test('renderInvoiceText line discount calculation precision', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 7, unitPrice: 9500, vatRate: 21, discountPercent: 5 },
    ],
  };
  const text = renderInvoiceText(invoice);
  // 7 * 9500 = 66500, discount 5% = 3325
  assert.ok(text.includes('(discount: -€33.25)'));
});

